<?php
$titulo_pagina='Minhas Publicações';$estilos_pagina=['/assets/css/admin.css?v=5'];require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';verificarProfissional();$perfil=pegar_perfil_profissional_por_usuario($_SESSION['usuario_id']);if(!$perfil){mensagem_erro('Complete seu perfil antes de publicar.');redirecionar('/dashboard/profissional.php');}$erros=[];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!validar_csrf($_POST['csrf_token']??''))$erros[]='A sessão expirou.';$acao=$_POST['acao']??'criar';if(!$erros&&$acao==='excluir'){$id=(int)($_POST['id']??0);$stmt=$mysqli->prepare('DELETE FROM publicacoes_profissionais WHERE id=? AND profissional_id=?');$stmt->bind_param('ii',$id,$perfil['id']);$stmt->execute();mensagem_sucesso('Publicação removida.');redirecionar('/dashboard/publicacoes.php');}$conteudo=trim($_POST['conteudo']??'');$imagem=trim($_POST['imagem_url']??'');if($acao==='criar'){if(mb_strlen($conteudo)<3)$erros[]='Escreva uma publicação.';if($imagem&&!filter_var($imagem,FILTER_VALIDATE_URL))$erros[]='A URL da imagem é inválida.';if(!$erros){$stmt=$mysqli->prepare('INSERT INTO publicacoes_profissionais(profissional_id,conteudo,imagem_url) VALUES(?,?,?)');$stmt->bind_param('iss',$perfil['id'],$conteudo,$imagem);$stmt->execute();mensagem_sucesso('Publicação adicionada ao feed público.');redirecionar('/dashboard/publicacoes.php');}}}
$stmt=$mysqli->prepare('SELECT * FROM publicacoes_profissionais WHERE profissional_id=? ORDER BY criado_em DESC');$stmt->bind_param('i',$perfil['id']);$stmt->execute();$publicacoes=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);require_once __DIR__.'/../includes/header.php';?>
<div class="container"><div class="page-heading"><div><h1>Minhas Publicações</h1><p>Tudo que você publicar será visível no feed público.</p></div></div><?php exibir_mensagens(); ?><?php if($erros): ?><div class="alerta alerta-erro"><?php echo sanitizar(implode(' ',$erros)); ?></div><?php endif; ?><form class="service-form" method="POST"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="criar"><div class="form-group"><label for="conteudo">O que deseja compartilhar?</label><textarea id="conteudo" name="conteudo" rows="5" maxlength="5000" required></textarea></div><div class="form-group"><label for="imagem_url">Imagem (URL opcional)</label><input id="imagem_url" name="imagem_url" type="url" placeholder="https://..."></div><button class="btn" type="submit">Publicar no feed</button></form><div class="posts-lista"><?php foreach($publicacoes as $post): ?><article class="post-item"><p><?php echo nl2br(sanitizar($post['conteudo'])); ?></p><small><?php echo date('d/m/Y H:i',strtotime($post['criado_em'])); ?></small><form method="POST" onsubmit="return confirm('Remover esta publicação?')"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?php echo (int)$post['id']; ?>"><button class="btn-small btn-danger">Excluir</button></form></article><?php endforeach; ?></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
